void frame_5527_0(Activation& scope) {
    stop();
    _root["warpframe"] = false;
    scope["onEnterFrame"] = scope.function([](Activation& scope) -> Value {
        if (scope.self["warp1"]["hitTest"](_root["Course"]["Char"]["charClip"]["feet"]) && _root["Course"]["Char"]["yspeed"] > 0) {
            _root["Course"]["Char"]["attack"] = true;
            _root["Course"]["Char"]["xspeed"] = 0;
            _root["Course"]["Char"]["yspeed"] = 0;
            _root["Course"]["Char"]["attackFrame"] = "none";
            scope["warp"] = true;
            scope["warpnum"] = 1;
        }
        if (scope["warp"] == true && _root["warpframe"] == false) {
            if (scope["warpnum"] == 1) {
                _root["attachMovie"]("downtransition", "downtransition" + _root["getNextHighestDepth"](), _root["getNextHighestDepth"](), obj({{"_x", _root["screensizeX"] / 2}, {"_y", _root["screensizeY"] / 2}}));
            }
            scope["warp"] = false;
        }
        if (_root["warpframe"] == true) {
            if (scope["warpnum"] == 1) {
                _root["changecourse"]("downtransition2", "8-10", 500, -1450, 500, -1450);
            }
            //_root.warpframe = false;
        }
        return undefined;
    });
}

